<script lang="ts">
 import '$lib/styles/design.css';import '$lib/styles/app.css';import '$lib/styles/database-native.css';import {databaseState,initDatabases} from '$lib/database/store';import {onMount} from 'svelte';import {page} from '$app/stores';import {groups,route} from '$lib/navigation';import Icon from '$lib/components/Icon.svelte';import {workspace,initWorkspace} from '$lib/stores/workspace';
 let drawer=false,searchOpen=false,search='';
 $: pathname=$page.url.pathname;$: parts=pathname.split('/').filter(Boolean);$: active=parts[0]||'get-started';$: project=active==='projects'&&parts[1]&&parts[1]!=='new'?$workspace.projects.find(p=>p.id===parts[1]):undefined;$: database=active==='databases'&&parts[1]&&parts[1]!=='users'?$databaseState.databases.find(d=>d.id===parts[1]):undefined;$: dbUser=active==='databases'&&parts[1]==='users'&&parts[2]?$databaseState.users.find(u=>u.id===parts[2]):undefined;$: activeName=groups.flatMap(g=>g[1]).find(s=>route(s)==='/'+active)||'Get started';$: matches=groups.flatMap(g=>g[1]).filter(s=>s.toLowerCase().includes(search.toLowerCase()));
 onMount(()=>{const dispose=initWorkspace();const disposeDb=initDatabases();try{const p=localStorage.getItem('drevanta-svelte-palette');if(p&&p!=='original')document.documentElement.dataset.palette=p;document.documentElement.classList.toggle('dark',localStorage.getItem('drevanta-svelte-mode')==='dark')}catch{}return ()=>{dispose();disposeDb();};});
</script>
<svelte:head><title>{project?.name||database?.name||dbUser?.name||activeName} · Drevanta</title></svelte:head>
<div class="dashboard"><a class="skip-link" href="#main">Skip to main content</a><aside class:open={drawer} class="sidebar" id="sidebar"><a class="brand" href="/get-started"><span class="brand-mark" aria-hidden="true">▦</span><span>dre<span class="brand-accent">vanta</span><small>SELF-HOSTED CONSOLE</small></span></a><nav aria-label="Main navigation">{#each groups as group}<div class="nav-section">{group[0]}</div>{#each group[1] as item}<a class:active={active===route(item).slice(1)} href={route(item)} aria-current={active===route(item).slice(1)?'page':undefined} on:click={()=>drawer=false}><Icon name={item}/>{item}</a>{/each}{/each}</nav><div class="sidebar-bottom"><div class="connection"><span class="dot warning"></span>Development · demo data</div><a class="user-card" href="/settings" style="text-decoration:none"><span class="avatar">AD</span><span><strong>Administrator</strong><small>Account &amp; preferences</small></span></a></div></aside>{#if drawer}<button class="drawer-backdrop" aria-label="Close navigation" on:click={()=>drawer=false}></button>{/if}<div class="dashboard-shell"><header class="topbar"><div class="top-left"><button class="icon-btn mobile-menu" aria-label="Open navigation" aria-expanded={drawer} aria-controls="sidebar" on:click={()=>drawer=!drawer}><Icon name="Menu"/></button><span class="quiet">Self-hosted console</span></div><div class="top-actions"><button class="icon-btn" aria-label="Search pages" on:click={()=>searchOpen=!searchOpen}><Icon name="Search"/></button><a class="avatar" href="/settings" style="text-decoration:none" aria-label="Account settings">AD</a></div></header>{#if searchOpen}<div class="card" style="margin:12px 24px"><label class="field">Search pages<input bind:value={search} placeholder="Search pages…"/></label><div class="native-inline native-note">{#each matches as item}<a class="btn secondary small" href={route(item)} on:click={()=>searchOpen=false}>{item}</a>{/each}</div></div>{/if}<div class="native-crumb-wrap"><nav class="native-crumb" aria-label="Breadcrumb"><a href="/overview">Dashboard</a><span>/</span>{#if project}<a href="/projects">Projects</a><span>/</span><a href={'/projects/'+project.id}>{project.name}</a>{#if parts[2]}<span>/</span><strong>{parts[2][0].toUpperCase()+parts[2].slice(1)}</strong>{/if}{:else if active==='databases'&&parts[1]}<a href="/databases">Databases</a><span>/</span>{#if parts[1]==='users'}{#if dbUser}<a href="/databases/users">Manage Users</a><span>/</span><strong>{dbUser.name}</strong>{:else}<strong>Manage Users</strong>{/if}{:else}<strong>{database?.name||'Manage Database'}</strong>{/if}{:else if active==='projects'&&parts[1]==='new'}<a href="/projects">Projects</a><span>/</span><strong>New project</strong>{:else}<strong>{activeName}</strong>{/if}</nav></div><main id="main" tabindex="-1">{#key pathname}<slot/>{/key}</main></div></div>
